SELECT a.hadm_id, a.los, p.gender_code, d.diagnosis_code, COUNT(i.imaging_study_id) AS num_imaging_studies, percentile_cont(0.25) within GROUP (ORDER BY COUNT(i.imaging_study_id)) AS p25, percentile_cont(0.75) within GROUP (ORDER BY COUNT(i.imaging_study_id)) AS p75 FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id JOIN imaging_studies i ON a.subject_id = i.subject_id AND a.hadm_id = i.hadm_id WHERE p.gender_code = 'M' AND d.diagnosis_code = '440.0' AND a.los BETWEEN 1 AND 7 AND (a.admittime - p.dob) BETWEEN 67 AND 77 GROUP BY a.hadm_id, a.los, p.gender_code, d.diagnosis_code ORDER BY a.hadm_id, a.los, p.gender_code, d.diagnosis_code NULLS LAST;